"""Build substantive service pages in English and Spanish, using shared brand assets."""
from html import escape as h
from seo import BASE,SLUGS,graph
COPY={
'en':[
 dict(name='Paid advertising',title='Google & Meta Ads Management | Keystone Growth',description='Google and Meta ad management for US service businesses. Work directly with Aaron Brenes on offers, campaigns, landing pages and inquiry tracking.',headline='Paid ads with a clear path to an inquiry.',intro='Reach potential customers on Google and Meta, then give them a focused next step. Aaron Brenes manages the strategy and execution directly, with campaigns built around your offer, service area, and sales process.',fit='For businesses that can respond to new inquiries',fit_p='Advertising is most useful when you have a clear service, the capacity to take on customers, and someone ready to answer questions. Before proposing a campaign, we review how a customer moves from the first inquiry to a quote, appointment, or purchase.',sections=[('Choose the channel around the customer','Google Search can support demand from people already looking for a service. Meta can introduce an offer to a relevant audience. We choose channels around your offer and market instead of assuming every business needs both.'),('Connect the ad to the next step','A campaign can lead to a dedicated landing page, inquiry form, or booking journey. We review the message and the destination together so prospects can understand the offer and know what happens when they contact you.'),('Measure the inquiries that matter','Where the available tools allow, we connect campaign reporting with form submissions or booking activity. Your team’s feedback about inquiry quality helps guide adjustments; clicks alone do not tell us whether a campaign supports the business.')],items=['Offer and audience review','Google Ads and/or Meta Ads setup and management','Campaign copy and creative requirements','Conversion-tracking review and reporting'],questions=[('Is advertising spend included?','No. Platform advertising spend is separate from management fees, website projects, software, and any messaging costs. The proposal identifies what is included.'),('Do you guarantee leads or sales?','No. Results depend on the offer, market, budget, sales process, and other factors. We agree on the scope and measurement before launch.'),('Can you handle Spanish-speaking US customers?','Yes. Campaign messaging and the inquiry journey can be adapted to English or Spanish. We confirm the audience and who will handle customer conversations.')]),
 dict(name='Websites & landing pages',title='Websites & Landing Pages for Service Businesses | Keystone Growth',description='Clear, mobile-friendly websites and campaign landing pages for US service businesses. Direct collaboration with Aaron Brenes from message to launch.',headline='Make it easy to understand your offer—and contact you.',intro='A website should help a potential customer decide whether your business is a fit. Keystone Growth builds focused websites and landing pages around a clear offer, useful information, and a straightforward path to an inquiry or booking.',fit='For businesses whose website is losing the next step',fit_p='You may need a new page when prospects arrive but cannot quickly understand your services, find an answer, or request a quote. We review the offer and customer journey before deciding whether to improve an existing page or build a new one.',sections=[('A page built for its traffic','A campaign landing page supports a specific offer and audience. A broader business website helps visitors understand multiple services and decide where to go next. The page structure follows the job it needs to do.'),('Clear copy and mobile layouts','We organize the offer, service details, questions, and contact options so they are easy to use on a phone. Forms ask for the information your team actually needs, and calls to action explain the next step.'),('Test the complete inquiry journey','Before launch, we check navigation, form validation, confirmation states, booking links, and the destination of notifications. Tracking and CRM connections are agreed in the scope, along with hosting and any platform dependencies.')],items=['Offer and page-structure planning','Website or landing-page copy and design','Mobile-friendly layouts and inquiry forms','Booking or CRM integrations where agreed'],questions=[('Do I need a whole new website?','Not always. A focused landing page or improvements to an existing site may be enough. We recommend the smallest useful scope for the problem.'),('Can the site be bilingual?','Yes. English and Spanish pages can share a brand while adapting the message, examples, and contact path to their audience.'),('Are hosting and ongoing edits included?','That depends on the proposal. Hosting, domain renewal, software, maintenance, and future edits are specified separately so responsibilities are clear.')]),
 dict(name='CRM & automation',title='CRM Setup & Lead Follow-Up Automation | Keystone Growth',description='Organize service-business inquiries with CRM pipelines, automated follow-up, reminders and booking workflows led by Aaron Brenes.',headline='Give every inquiry an owner and a next step.',intro='Keystone Growth connects forms, lead pipelines, and follow-up workflows so your team can see what needs attention. Automations handle agreed routine steps while people handle the conversations that require judgment.',fit='For teams losing track between the inquiry and the sale',fit_p='If contacts sit in separate inboxes, reminders depend on memory, or no one knows who should reply, the first priority is a practical process. We map your current tools and sales stages before adding software or automation.',sections=[('Start with a pipeline people can use','We define stages such as new inquiry, contacted, appointment booked, and closed around your actual process. Ownership and next actions matter more than building a complicated dashboard no one updates.'),('Automate the repeatable work','Depending on your tools and permissions, workflows can acknowledge an inquiry, assign a lead, create a task, send a booking reminder, or run a follow-up sequence. Channel availability and message permissions are confirmed before anything is enabled.'),('Keep a human path through the process','Automation should support the team’s work. We agree where staff take over, how replies are handled, and what stops a sequence. Your team remains responsible for live sales conversations unless a different scope is agreed.')],items=['Lead journey and tool review','CRM pipeline and field setup','Form routing, tasks, and booking workflows','Agreed follow-up sequences and handoff documentation'],questions=[('Do you call and close my leads?','Human lead handling and closing are not included in the standard scope. Automation supports the process; your team handles conversations and sales unless separately agreed.'),('Can you use my current CRM?','We first review its capabilities, access, and available integrations. We propose changes based on what your existing setup can support.'),('Are software and messaging costs included?','No. Licenses, email or SMS usage, and third-party integration costs are separate from project or management fees and are identified in the proposal.')])],
'es':[
 dict(name='Publicidad digital',title='Gestión de Google Ads y Meta Ads en Latinoamérica | Keystone Growth',description='Publicidad en Google y Meta para negocios en Latinoamérica. Trabajá con Aaron Brenes en ofertas, campañas y seguimiento de consultas.',headline='Publicidad que conecta tu oferta con el siguiente paso.',intro='Llegá a posibles clientes con campañas en Google y Meta adaptadas a tu país, tu oferta y tu forma de vender. Trabajás directamente con Aaron Brenes para conectar el anuncio con una consulta que tu negocio pueda atender.',fit='Para negocios que pueden atender más consultas',fit_p='Antes de invertir, revisamos qué vendés, dónde atendés y quién responde los contactos. Si las consultas se quedan sin respuesta, aumentar el presupuesto no resuelve esa parte del proceso. La propuesta parte de lo que tu negocio necesita mejorar.',sections=[('Elegimos el canal según tu mercado','Google puede captar búsquedas de personas que ya necesitan un servicio. Meta puede presentar una oferta a una audiencia relevante. Definimos la combinación según la demanda, el presupuesto y el objetivo; no todos los negocios necesitan ambos canales.'),('El anuncio y la página deben decir lo mismo','Revisamos la oferta y el destino de la campaña para que la persona entienda qué ofrecés y cómo contactarte. El siguiente paso puede ser un formulario, una reserva o un contacto por WhatsApp, según las herramientas y el alcance acordado.'),('Revisamos consultas, no solo clics','Los reportes ayudan a entender qué campañas generan contactos. La información que comparte tu equipo sobre calidad de consultas y ventas permite orientar los ajustes, junto con los datos que se puedan medir de forma confiable.')],items=['Revisión de oferta, público y zona de atención','Configuración y gestión de Google Ads o Meta Ads','Mensajes y requisitos de los creativos','Revisión de medición y reportes de campañas'],questions=[('¿El presupuesto de anuncios está incluido?','No. La inversión que se paga a Google o Meta va por separado de los honorarios, el sitio web, el software y los mensajes.'),('¿Podés trabajar con un presupuesto pequeño?','Primero revisamos el país, la competencia, el servicio y el objetivo. Un presupuesto bajo puede requerir un alcance más limitado; no prometemos el mismo resultado para todos los mercados.'),('¿Garantizás ventas?','No. Las ventas también dependen de la oferta, la atención, los precios y el proceso comercial. Acordamos qué vamos a hacer y cómo revisar el avance.')]),
 dict(name='Sitios web y landing pages',title='Sitios Web y Landing Pages para Negocios | Keystone Growth',description='Sitios web y landing pages para negocios en Latinoamérica: mensajes claros, diseño para celulares y contacto por formularios o reservas.',headline='Una web que explique tu negocio y facilite el contacto.',intro='Construimos sitios web y landing pages con una oferta fácil de entender y un siguiente paso claro. Desde Costa Rica, Aaron Brenes trabaja directamente con negocios en Latinoamérica para conectar sus campañas con una mejor experiencia de consulta.',fit='Para negocios que necesitan algo más útil que una tarjeta digital',fit_p='Tu página debe responder lo que una persona necesita saber antes de escribirte: qué ofrecés, para quién es y cómo empezar. Podemos mejorar una web existente o crear una página enfocada en una campaña, según el problema que encontremos.',sections=[('Una estructura según lo que vendés','Una landing page se concentra en una oferta o campaña. Un sitio de negocio organiza varios servicios y ayuda a comparar opciones. Definimos las secciones a partir de las preguntas reales de tus posibles clientes.'),('Pensado para quienes te visitan desde el celular','Revisamos legibilidad, botones y formularios para facilitar el primer contacto. Si atendés por WhatsApp, ese camino puede incorporarse al alcance sin obligar a todos los visitantes a usar el mismo canal.'),('Probamos desde la visita hasta la consulta','Verificamos enlaces, campos del formulario, confirmaciones, notificaciones y reservas antes de publicar. También dejamos claras las responsabilidades de dominio, hosting, accesos y futuras modificaciones.')],items=['Plan de contenido y estructura','Diseño y mensajes para web o landing page','Formularios y experiencia en celulares','Integraciones de contacto acordadas'],questions=[('¿Necesito comprar otro dominio?','No necesariamente. Podemos revisar el dominio y el hosting que ya tenés antes de recomendar un cambio.'),('¿Podés crear una versión en inglés?','Sí. Adaptamos el mensaje y el recorrido al público de cada idioma, manteniendo una identidad de marca consistente.'),('¿Incluye mantenimiento?','Los cambios futuros, el mantenimiento, las plataformas y el hosting se especifican en la propuesta. No se asumen incluidos sin definir el alcance.')]),
 dict(name='CRM y automatización',title='CRM y Automatización de Seguimiento en Latinoamérica | Keystone Growth',description='Ordená consultas, CRM y seguimiento automático para tu negocio en Latinoamérica. Formularios, recordatorios e integraciones según tu proceso.',headline='Que la próxima consulta no se pierda entre mensajes.',intro='Organizá los contactos y definí qué pasa después de cada consulta. Keystone Growth conecta formularios, CRM y herramientas de seguimiento para reducir tareas repetitivas y darle a tu equipo un proceso que pueda usar.',fit='Para negocios que venden entre chats, correos y recordatorios',fit_p='Si los contactos están repartidos entre varias herramientas o el seguimiento depende de acordarse, primero revisamos cómo trabajan hoy. El objetivo es dar claridad sobre quién atiende, qué información se guarda y cuándo toca volver a contactar.',sections=[('Un proceso que refleje tu forma de vender','Definimos etapas y campos útiles para tu equipo. Una consulta nueva, una cotización enviada y una venta cerrada necesitan acciones distintas. El CRM debe mostrar esas diferencias sin complicar la atención.'),('Automatizamos lo que tiene sentido','Los flujos pueden confirmar la recepción, asignar contactos, crear tareas y enviar recordatorios o seguimiento acordado. Si usás WhatsApp, revisamos qué integración es viable y cuáles son sus requisitos y costos antes de ofrecerla.'),('Las conversaciones siguen teniendo una persona responsable','Definimos dónde interviene tu equipo, qué pasa cuando alguien responde y cómo detener una secuencia. Los mensajes automáticos complementan la atención; no incluyen llamadas personales ni cierre de ventas en el alcance estándar.')],items=['Revisión del recorrido de consultas','Etapas y campos del CRM','Asignaciones, tareas y recordatorios','Secuencias acordadas y documentación para el equipo'],questions=[('¿Funciona con WhatsApp Business?','Depende de la herramienta y de la integración disponible. Revisamos si requiere una plataforma o API, permisos adicionales y cargos de mensajería; no asumimos que cualquier aplicación se conecta automáticamente.'),('¿Tengo que cambiar de CRM?','Primero revisamos el sistema que ya usás. Podemos plantear mejoras sobre esa base si permite las funciones que necesitás.'),('¿El software está incluido?','No. Licencias, mensajes e integraciones se cotizan por separado de la implementación y del soporte. La propuesta detalla esos costos y responsabilidades.')])]
}
def build_services(root,data,calendar):
 for lang,pages in COPY.items():
  es=lang=='es'; home=f'/{lang}/'; other='en' if es else 'es'
  for i,c in enumerate(pages):
   path=home+SLUGS[lang][i]; pair='/'+other+'/'+SLUGS[other][i]
   sections=''.join(f'<article><h2>{h(title)}</h2><p>{h(body)}</p></article>' for title,body in c['sections'])
   faqs=''.join(f'<details><summary>{h(q)}</summary><p>{h(a)}</p></details>' for q,a in c['questions'])
   links=''.join(f'<a href="{home+SLUGS[lang][j]}">{h(s["name"])}</a>' for j,s in enumerate(pages) if j!=i)
   items=''.join(f'<li>{h(x)}</li>' for x in c['items'])
   title=h(c['title']);desc=h(c['description'],quote=True)
   page=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{BASE+path}"><link rel="alternate" hreflang="{lang}" href="{BASE+path}"><link rel="alternate" hreflang="{other}" href="{BASE+pair}"><link rel="alternate" hreflang="x-default" href="{BASE+('/en/'+SLUGS['en'][i])}"><link rel="stylesheet" href="/assets/site.css"><link rel="icon" type="image/svg+xml" href="/assets/keystone-icon-v2.svg"><link rel="icon" type="image/png" sizes="32x32" href="/assets/keystone-icon-32.png"><link rel="apple-touch-icon" href="/assets/keystone-touch-icon.png"><meta name="theme-color" content="#041C35"><meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{BASE+path}"><meta property="og:image" content="{BASE}/assets/social-card.png"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{graph(lang,c['title'],c['description'],path,c['name'])}</script></head><body><a class="skip" href="#main">{'Saltar al contenido' if es else 'Skip to content'}</a><header><div class="wrap header-row"><a class="brand" href="{home}" aria-label="Keystone Growth"><img src="/assets/logo-light.svg" width="200" height="48" alt="Keystone Growth"></a><nav class="service-nav" aria-label="{'Principal' if es else 'Main'}"><a href="{home}#services">{'Servicios' if es else 'Services'}</a><a href="{home}#contact">{'Contacto' if es else 'Contact'}</a></nav><div class="language"><a href="{path}" lang="{lang}" aria-current="page">{lang.upper()}</a><a href="{pair}" lang="{other}">{other.upper()}</a></div></div></header><main id="main"><section class="service-hero dark"><div class="wrap"><nav class="breadcrumbs" aria-label="{'Ruta de navegación' if es else 'Breadcrumb'}"><a href="{home}">{'Inicio' if es else 'Home'}</a><span aria-hidden="true">/</span><span>{h(c['name'])}</span></nav><p class="eyebrow">{'Keystone Growth · Latinoamérica' if es else 'Keystone Growth · US service businesses'}</p><h1>{h(c['headline'])}</h1><p class="service-lead">{h(c['intro'])}</p><a class="btn" href="{home}#contact">{'Hablemos de tu negocio' if es else 'Discuss your business'} <span aria-hidden="true">↗</span></a></div></section><section class="section"><div class="wrap service-content"><div><div class="service-fit"><h2>{h(c['fit'])}</h2><p>{h(c['fit_p'])}</p></div>{sections}</div><aside><h2>{'Qué puede incluir' if es else 'What a scope can include'}</h2><ul>{items}</ul><p>{'El alcance se confirma en una propuesta. Inversión publicitaria, software y mensajes se pagan por separado.' if es else 'Your proposal confirms the deliverables. Advertising spend, software, and messaging costs are separate.'}</p><p>{'Estrategia y comunicación: Aaron Brenes, fundador. Más de tres años gestionando campañas. Atención en español e inglés.' if es else 'Strategy and communication: Aaron Brenes, founder. More than three years managing campaigns. English and Spanish support.'}</p><a class="text-link" href="{home}#about">{'Conocé a Aaron' if es else 'Meet Aaron'}</a></aside></div></section><section class="section service-questions"><div class="wrap"><h2>{'Preguntas frecuentes' if es else 'Questions before getting started'}</h2><div class="faq">{faqs}</div></div></section><section class="section dark"><div class="wrap service-close"><h2>{'Definamos el siguiente paso.' if es else 'Let’s define the next step.'}</h2><p>{'Contame tu país, qué vendés y dónde se está trabando el proceso.' if es else 'Tell me what you sell, where you operate, and what needs to improve.'}</p><a class="btn" href="{calendar}" target="_blank" rel="noopener noreferrer">{'Agendá una llamada' if es else 'Book a discovery call'}</a><a href="mailto:aaron@keystonegrowth.org">aaron@keystonegrowth.org</a></div></section></main><footer><div class="wrap"><p>{'Otros servicios' if es else 'Related services'}</p><nav class="related-services">{links}</nav><div class="footer-bottom"><span>© 2026 Keystone Growth</span><div class="footer-links"><a href="/privacy.html">{'Privacidad (inglés)' if es else 'Privacy'}</a><a href="/terms.html">{'Términos (inglés)' if es else 'Terms'}</a></div></div></div></footer></body></html>'''
   target=root/path.lstrip('/')/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(page)
